package com.neilb.nonocraft.presentation.screens.dashboard.components

import androidx.compose.foundation.Canvas
import androidx.compose.foundation.background
import androidx.compose.foundation.border
import androidx.compose.foundation.clickable
import androidx.compose.foundation.interaction.MutableInteractionSource
import androidx.compose.foundation.layout.*
import androidx.compose.foundation.shape.RoundedCornerShape
import androidx.compose.material.icons.Icons
import androidx.compose.material.icons.automirrored.filled.LibraryBooks
import androidx.compose.material.icons.automirrored.filled.MenuBook
import androidx.compose.material.icons.automirrored.outlined.LibraryBooks
import androidx.compose.material.icons.automirrored.outlined.MenuBook
import androidx.compose.material.icons.filled.AccountCircle
import androidx.compose.material.icons.filled.CollectionsBookmark
import androidx.compose.material.icons.filled.Explore
import androidx.compose.material.icons.filled.Home
import androidx.compose.material.icons.filled.PlayArrow
import androidx.compose.material.icons.outlined.AccountCircle
import androidx.compose.material.icons.outlined.CollectionsBookmark
import androidx.compose.material.icons.outlined.Explore
import androidx.compose.material.icons.outlined.Home
import androidx.compose.material.icons.outlined.PlayArrow
import androidx.compose.material3.Icon
import androidx.compose.material3.NavigationBar
import androidx.compose.material3.NavigationBarItem
import androidx.compose.material3.NavigationBarItemDefaults
import androidx.compose.material3.Text
import androidx.compose.runtime.Composable
import androidx.compose.ui.Modifier
import androidx.compose.ui.draw.clip
import androidx.compose.ui.geometry.Offset
import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.text.font.FontWeight
import androidx.compose.ui.unit.dp
import androidx.compose.ui.unit.sp
import com.neilb.nonocraft.presentation.theme.*

// ─── Bottom nav item modeli ────────────────────────────────────────────────────
data class DashboardTabItem(
    val label: String,
    val filledIcon: ImageVector,
    val outlinedIcon: ImageVector
)

enum class DashboardTab(val tabItem: DashboardTabItem) {
    PLAYGROUND(DashboardTabItem("Oyun Alanı", Icons.Filled.PlayArrow, Icons.Outlined.PlayArrow)),
    FEED(DashboardTabItem("Keşfet", Icons.Filled.Explore, Icons.Outlined.Explore)),
    LIBRARY(DashboardTabItem("Koleksiyon", Icons.Filled.CollectionsBookmark, Icons.Outlined.CollectionsBookmark)),
    ACCOUNT(DashboardTabItem("Profil", Icons.Filled.AccountCircle, Icons.Outlined.AccountCircle))
}

// ─── Material 3 Standart Bottom Navigation Bar ─────────────────────────────────
@Composable
fun DashboardBottomNavBar(
    currentTab: DashboardTab,
    onTabSelected: (DashboardTab) -> Unit,
    modifier: Modifier = Modifier,
) {
    NavigationBar(
        modifier = modifier.border(width = 0.5.dp, color = BorderDark),
        containerColor = SurfaceDark,
        contentColor = TextMuted,
        tonalElevation = 0.dp // Tasarımın flat kalması için
    ) {
        DashboardTab.entries.forEach { tab ->
            val isSelected = tab == currentTab
            val tabItem = tab.tabItem

            NavigationBarItem(
                selected = isSelected,
                onClick = { onTabSelected(tab) },
                icon = {
                    Icon(
                        imageVector = if (isSelected) tabItem.filledIcon else tabItem.outlinedIcon,
                        contentDescription = tabItem.label,
                        modifier = Modifier.size(24.dp)
                    )
                },
                label = {
                    Text(
                        text = tabItem.label,
                        fontSize = 11.sp,
                        fontFamily = AppFont,
                        fontWeight = if (isSelected) FontWeight.SemiBold else FontWeight.Medium
                    )
                },
                colors = NavigationBarItemDefaults.colors(
                    selectedIconColor = NeonCyan,
                    selectedTextColor = NeonCyan,
                    unselectedIconColor = TextMuted,
                    unselectedTextColor = TextMuted,
                    indicatorColor = NeonCyan.copy(alpha = 0.15f) // İkon arkasındaki M3 vurgu rengi
                )
            )
        }
    }
}

// ─── Tüm dashboard sayfalarında kullanılan arka plan grid çizgisi ─────────────
@Composable
fun DashboardGridBackground(modifier: Modifier = Modifier) {
    Canvas(modifier = modifier.fillMaxSize()) {
        val step = 72f
        val color = NeonCyan.copy(alpha = 0.025f)
        var x = 0f
        while (x <= size.width) {
            drawLine(color, Offset(x, 0f), Offset(x, size.height), strokeWidth = 1f)
            x += step
        }
        var y = 0f
        while (y <= size.height) {
            drawLine(color, Offset(0f, y), Offset(size.width, y), strokeWidth = 1f)
            y += step
        }
    }
}

// ─── Section label (uppercase, letter-spaced) ─────────────────────────────────
@Composable
fun SectionLabel(text: String, modifier: Modifier = Modifier) {
    Text(
        text = text.uppercase(),
        color = TextMuted,
        fontSize = 11.sp,
        letterSpacing = 1.2.sp,
        fontFamily = AppFont,
        fontWeight = FontWeight.Medium,
        modifier = modifier.padding(bottom = 8.dp),
    )
}

// ─── Genel amaçlı kart container ──────────────────────────────────────────────
@Composable
fun DashboardCard(
    modifier: Modifier = Modifier,
    backgroundColor: Color = SurfaceDark,
    borderColor: Color = BorderDark,
    cornerRadius: Int = 16,
    content: @Composable () -> Unit,
) {
    Box(
        modifier = modifier
            .clip(RoundedCornerShape(cornerRadius.dp))
            .background(backgroundColor)
            .border(0.5.dp, borderColor, RoundedCornerShape(cornerRadius.dp)),
    ) {
        content()
    }
}

// ─── Ripple olmadan tıklanabilir modifier ─────────────────────────────────────
fun Modifier.noRippleClickable(onClick: () -> Unit): Modifier = this.clickable(
    interactionSource = MutableInteractionSource(),
    indication = null,
    onClick = onClick,
)

